-- Immutable per-config AS dynamic client registration. Drain all pre-0065 writers first.
-- No real AS registration, credential backfill, remote revocation or lifecycle completion occurs in DDL.
-- The final full root must be calibrated on an independent explicit MySQL fixture before use.
SET @mcp_dcr_previous_gcml=@@SESSION.group_concat_max_len;
SET SESSION group_concat_max_len=1048576;
SET @skill_registry_triggers_ok=(
  (SELECT COUNT(*)=17 FROM information_schema.tables WHERE table_schema=DATABASE() AND (table_name LIKE 'mcp_registry_%' OR table_name LIKE 'tenant_webhook_%' OR table_name LIKE 'subagent_%'))
  AND (SELECT COUNT(*)=0 FROM information_schema.partitions WHERE table_schema=DATABASE() AND (table_name LIKE 'mcp_registry_%' OR table_name LIKE 'tenant_webhook_%' OR table_name LIKE 'subagent_%') AND partition_name IS NOT NULL)
  AND (SELECT COUNT(*)=842 AND SUM(trigger_name LIKE 'trg_tenant_webhook%')=23 AND SUM(trigger_name LIKE 'trg_subagent%')=24 AND SUM(OCTET_LENGTH(CONCAT_WS('~',event_object_table,trigger_name,action_timing,event_manipulation,action_orientation,IFNULL(action_condition,'<NULL>'),LOWER(REPLACE(REPLACE(REGEXP_REPLACE(action_statement,'[[:space:]]',''),CHAR(96),''),'_utf8mb4','')))))+COUNT(*)-1<=@@SESSION.group_concat_max_len FROM information_schema.triggers WHERE trigger_schema=DATABASE())
  AND SHA2(CONCAT_WS('::',
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,engine,table_collation,row_format,create_options) ORDER BY table_name SEPARATOR '|'),256) FROM information_schema.tables WHERE table_schema=DATABASE() AND (table_name LIKE 'mcp_registry_%' OR table_name LIKE 'tenant_webhook_%' OR table_name LIKE 'subagent_%')),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,LPAD(ordinal_position,3,'0'),column_name,column_type,is_nullable,IFNULL(column_default,'<NULL>'),extra,IFNULL(character_set_name,'-'),IFNULL(collation_name,'-'),LOWER(REPLACE(REPLACE(REGEXP_REPLACE(IFNULL(generation_expression,''),'[[:space:]]',''),CHAR(96),''),'_utf8mb4',''))) ORDER BY table_name,ordinal_position SEPARATOR '|'),256) FROM information_schema.columns WHERE table_schema=DATABASE() AND (table_name LIKE 'mcp_registry_%' OR table_name LIKE 'tenant_webhook_%' OR table_name LIKE 'subagent_%')),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,index_name,LPAD(seq_in_index,3,'0'),column_name,non_unique,index_type,IFNULL(collation,'-'),IFNULL(sub_part,'-'),IFNULL(nullable,'-')) ORDER BY table_name,index_name,seq_in_index SEPARATOR '|'),256) FROM information_schema.statistics WHERE table_schema=DATABASE() AND (table_name LIKE 'mcp_registry_%' OR table_name LIKE 'tenant_webhook_%' OR table_name LIKE 'subagent_%')),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,constraint_name,constraint_type,IFNULL(enforced,'-')) ORDER BY table_name,constraint_name SEPARATOR '|'),256) FROM information_schema.table_constraints WHERE table_schema=DATABASE() AND (table_name LIKE 'mcp_registry_%' OR table_name LIKE 'tenant_webhook_%' OR table_name LIKE 'subagent_%')),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',constraint_name,LOWER(REPLACE(REPLACE(REGEXP_REPLACE(check_clause,'[[:space:]]',''),CHAR(96),''),'_utf8mb4',''))) ORDER BY constraint_name SEPARATOR '|'),256) FROM information_schema.check_constraints WHERE constraint_schema=DATABASE() AND (constraint_name='chk_mcp_owner' OR constraint_name='chk_tenant_webhook_slot_state' OR constraint_name LIKE 'chk_subagent_%')),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,constraint_name,referenced_table_name,update_rule,delete_rule) ORDER BY table_name,constraint_name SEPARATOR '|'),256) FROM information_schema.referential_constraints WHERE constraint_schema=DATABASE() AND (table_name LIKE 'mcp_registry_%' OR table_name LIKE 'tenant_webhook_%' OR table_name LIKE 'subagent_%')),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,constraint_name,LPAD(ordinal_position,3,'0'),column_name,referenced_table_name,referenced_column_name) ORDER BY table_name,constraint_name,ordinal_position SEPARATOR '|'),256) FROM information_schema.key_column_usage WHERE table_schema=DATABASE() AND (table_name LIKE 'mcp_registry_%' OR table_name LIKE 'tenant_webhook_%' OR table_name LIKE 'subagent_%') AND referenced_table_name IS NOT NULL),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',event_object_table,trigger_name,action_timing,event_manipulation,action_orientation,IFNULL(action_condition,'<NULL>'),LOWER(REPLACE(REPLACE(REGEXP_REPLACE(action_statement,'[[:space:]]',''),CHAR(96),''),'_utf8mb4',''))) ORDER BY event_object_table,trigger_name SEPARATOR '|'),256) FROM information_schema.triggers WHERE trigger_schema=DATABASE())
  ),256)='dd0ec03f55e1ca18e541f0bede4132cad826f10c926f505991994028db8d666a'
);
SET @mcp_dcr_marker_ok=(SELECT COUNT(*)=1 FROM schema_migrations WHERE BINARY name=BINARY '0064_subagents.sql');
SET @migration_sql=IF(@skill_registry_triggers_ok=1 AND @mcp_dcr_marker_ok=1,'SELECT 1','SELECT 1 FROM __invalid_mcp_dcr_predecessor__');
PREPARE migration_stmt FROM @migration_sql;
EXECUTE migration_stmt;
DEALLOCATE PREPARE migration_stmt;

CREATE TABLE mcp_registry_dynamic_clients (
  operation_id CHAR(36) COLLATE utf8mb4_0900_as_cs NOT NULL,
  registration_id CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  subject_tenant_id VARCHAR(128) COLLATE utf8mb4_0900_as_cs NULL,
  subject_user_id VARCHAR(128) COLLATE utf8mb4_0900_as_cs NULL,
  record_json JSON NOT NULL,
  config_version_id CHAR(36) COLLATE utf8mb4_0900_as_cs GENERATED ALWAYS AS (JSON_UNQUOTE(JSON_EXTRACT(record_json,'$.configVersionId'))) STORED,
  operation_state VARCHAR(32) COLLATE utf8mb4_0900_as_cs GENERATED ALWAYS AS (JSON_UNQUOTE(JSON_EXTRACT(record_json,'$.state'))) STORED,
  idempotency_key_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs GENERATED ALWAYS AS (JSON_UNQUOTE(JSON_EXTRACT(record_json,'$.idempotencyKeySha256'))) STORED,
  PRIMARY KEY(operation_id), UNIQUE KEY uk_mcp_dcr_config(config_version_id), UNIQUE KEY uk_mcp_dcr_idempotency(idempotency_key_sha256),
  KEY idx_mcp_dcr_registration(registration_id,config_version_id),
  CONSTRAINT fk_mcp_dcr_registration FOREIGN KEY(registration_id) REFERENCES mcp_registry_controls(registration_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_mcp_dcr_version FOREIGN KEY(config_version_id) REFERENCES mcp_registry_versions(config_version_id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT chk_mcp_dcr_subject CHECK(subject_tenant_id IS NULL AND subject_user_id IS NULL),
  CONSTRAINT chk_mcp_dcr_state CHECK(operation_state IN ('prepared','sending','succeeded','failed_not_dispatched','outcome_unknown'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs;

CREATE TRIGGER trg_mcp_registry_dynamic_clients_bi BEFORE INSERT ON mcp_registry_dynamic_clients FOR EACH ROW BEGIN IF (JSON_LENGTH(NEW.record_json)=20 AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.operationId'))=BINARY NEW.operation_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.registrationId'))=BINARY NEW.registration_id AND NEW.operation_state='prepared' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.requestSha256')) REGEXP '^[a-f0-9]{64}$' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.idempotencyKeySha256')) REGEXP '^[a-f0-9]{64}$' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.claimTokenSha256')) REGEXP '^[a-f0-9]{64}$' AND JSON_TYPE(JSON_EXTRACT(NEW.record_json,'$.createdAtMs')) IN ('INTEGER','UNSIGNED INTEGER') AND JSON_EXTRACT(NEW.record_json,'$.createdAtMs')>=0 AND JSON_TYPE(JSON_EXTRACT(NEW.record_json,'$.deadlineAtMs')) IN ('INTEGER','UNSIGNED INTEGER') AND JSON_EXTRACT(NEW.record_json,'$.deadlineAtMs')>JSON_EXTRACT(NEW.record_json,'$.createdAtMs') AND JSON_EXTRACT(NEW.record_json,'$.deadlineAtMs')-JSON_EXTRACT(NEW.record_json,'$.createdAtMs') BETWEEN 100 AND 120000 AND JSON_EXTRACT(NEW.record_json,'$.sentAtMs')=CAST('null' AS JSON) AND JSON_EXTRACT(NEW.record_json,'$.completedAtMs')=CAST('null' AS JSON) AND JSON_EXTRACT(NEW.record_json,'$.clientId')=CAST('null' AS JSON) AND JSON_EXTRACT(NEW.record_json,'$.responseSha256')=CAST('null' AS JSON) AND JSON_EXTRACT(NEW.record_json,'$.resultSha256')=CAST('null' AS JSON) AND JSON_EXTRACT(NEW.record_json,'$.clientSecretCommitmentSha256')=CAST('null' AS JSON) AND JSON_EXTRACT(NEW.record_json,'$.clientSecretExpiresAtMs')=CAST('null' AS JSON) AND JSON_EXTRACT(NEW.record_json,'$.clientMaterial')=CAST('null' AS JSON) AND EXISTS (SELECT 1 FROM mcp_registry_versions v JOIN mcp_registry_controls c ON c.registration_id=v.registration_id WHERE v.config_version_id=NEW.config_version_id AND BINARY v.config_version_id=BINARY NEW.config_version_id AND v.registration_id=NEW.registration_id AND BINARY v.registration_id=BINARY NEW.registration_id AND JSON_UNQUOTE(JSON_EXTRACT(v.record_json,'$.config.authentication.kind'))='oauth_dynamic' AND JSON_EXTRACT(v.record_json,'$.owner')=JSON_EXTRACT(NEW.record_json,'$.owner') AND JSON_EXTRACT(v.record_json,'$.generation')=JSON_EXTRACT(NEW.record_json,'$.registrationGeneration') AND JSON_EXTRACT(v.record_json,'$.revision')<=JSON_EXTRACT(NEW.record_json,'$.registrationRevision') AND JSON_UNQUOTE(JSON_EXTRACT(c.record_json,'$.state'))='enabled' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(c.record_json,'$.currentVersionId'))=BINARY NEW.config_version_id AND JSON_EXTRACT(c.record_json,'$.revision')=JSON_EXTRACT(NEW.record_json,'$.registrationRevision') FOR SHARE)) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP DCR requires exact prepared config'; END IF; END;

CREATE TRIGGER trg_mcp_registry_dynamic_clients_bu BEFORE UPDATE ON mcp_registry_dynamic_clients FOR EACH ROW BEGIN IF (BINARY NEW.operation_id=BINARY OLD.operation_id AND BINARY NEW.registration_id=BINARY OLD.registration_id AND NEW.subject_tenant_id IS NULL AND NEW.subject_user_id IS NULL AND (NOT ((OLD.operation_state='prepared' AND NEW.operation_state='sending') OR (OLD.operation_state='sending' AND NEW.operation_state='succeeded')) OR EXISTS (SELECT 1 FROM mcp_registry_controls c WHERE c.registration_id=NEW.registration_id AND BINARY c.registration_id=BINARY NEW.registration_id AND JSON_UNQUOTE(JSON_EXTRACT(c.record_json,'$.state'))='enabled' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(c.record_json,'$.currentVersionId'))=BINARY NEW.config_version_id AND JSON_EXTRACT(c.record_json,'$.revision')=JSON_EXTRACT(NEW.record_json,'$.registrationRevision') FOR SHARE)) AND JSON_LENGTH(NEW.record_json)=20 AND ((NEW.operation_state='sending' AND JSON_EXTRACT(NEW.record_json,'$.completedAtMs')=CAST('null' AS JSON) AND JSON_EXTRACT(NEW.record_json,'$.resultSha256')=CAST('null' AS JSON) AND JSON_TYPE(JSON_EXTRACT(NEW.record_json,'$.sentAtMs')) IN ('INTEGER','UNSIGNED INTEGER') AND JSON_EXTRACT(NEW.record_json,'$.sentAtMs')>=JSON_EXTRACT(NEW.record_json,'$.createdAtMs') AND JSON_EXTRACT(NEW.record_json,'$.sentAtMs')<JSON_EXTRACT(NEW.record_json,'$.deadlineAtMs') AND JSON_EXTRACT(NEW.record_json,'$.deadlineAtMs')>CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED)) OR (NEW.operation_state<>'sending' AND JSON_TYPE(JSON_EXTRACT(NEW.record_json,'$.completedAtMs')) IN ('INTEGER','UNSIGNED INTEGER') AND JSON_EXTRACT(NEW.record_json,'$.completedAtMs')>=JSON_EXTRACT(NEW.record_json,'$.createdAtMs') AND ((OLD.operation_state='prepared' AND JSON_EXTRACT(NEW.record_json,'$.sentAtMs')=CAST('null' AS JSON)) OR (OLD.operation_state<>'prepared' AND JSON_EXTRACT(NEW.record_json,'$.sentAtMs')=JSON_EXTRACT(OLD.record_json,'$.sentAtMs'))))) AND JSON_REMOVE(NEW.record_json,'$.state','$.sentAtMs','$.completedAtMs','$.clientId','$.responseSha256','$.resultSha256','$.clientSecretCommitmentSha256','$.clientSecretExpiresAtMs','$.clientMaterial')=JSON_REMOVE(OLD.record_json,'$.state','$.sentAtMs','$.completedAtMs','$.clientId','$.responseSha256','$.resultSha256','$.clientSecretCommitmentSha256','$.clientSecretExpiresAtMs','$.clientMaterial') AND ((((OLD.operation_state='prepared' AND NEW.operation_state IN ('sending','failed_not_dispatched','outcome_unknown')) OR (OLD.operation_state='sending' AND NEW.operation_state IN ('succeeded','outcome_unknown'))) AND ((NEW.operation_state IN ('sending','failed_not_dispatched','outcome_unknown') AND JSON_EXTRACT(NEW.record_json,'$.clientId')=CAST('null' AS JSON) AND JSON_EXTRACT(NEW.record_json,'$.responseSha256')=CAST('null' AS JSON) AND JSON_EXTRACT(NEW.record_json,'$.clientSecretCommitmentSha256')=CAST('null' AS JSON) AND JSON_EXTRACT(NEW.record_json,'$.clientSecretExpiresAtMs')=CAST('null' AS JSON) AND JSON_EXTRACT(NEW.record_json,'$.clientMaterial')=CAST('null' AS JSON)) OR (NEW.operation_state='succeeded' AND EXISTS (SELECT 1 FROM mcp_registry_versions v WHERE v.config_version_id=NEW.config_version_id AND BINARY v.config_version_id=BINARY NEW.config_version_id AND ((JSON_UNQUOTE(JSON_EXTRACT(v.record_json,'$.config.authentication.clientAuthentication'))='none' AND JSON_EXTRACT(NEW.record_json,'$.clientSecretCommitmentSha256')=CAST('null' AS JSON) AND JSON_EXTRACT(NEW.record_json,'$.clientSecretExpiresAtMs')=CAST('null' AS JSON) AND JSON_EXTRACT(NEW.record_json,'$.clientMaterial')=CAST('null' AS JSON)) OR (JSON_UNQUOTE(JSON_EXTRACT(v.record_json,'$.config.authentication.clientAuthentication'))='client_secret_basic' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.clientSecretCommitmentSha256')) REGEXP '^[a-f0-9]{64}$' AND JSON_LENGTH(JSON_EXTRACT(NEW.record_json,'$.clientMaterial'))=3 AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.clientMaterial.materialId'))=BINARY NEW.operation_id AND JSON_LENGTH(JSON_EXTRACT(NEW.record_json,'$.clientMaterial.aad'))=13 AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.clientMaterial.aad.profile'))='mcp-secret-aad-v1' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.clientMaterial.aad.purpose'))='as_dynamic_client' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.clientMaterial.aad.registrationId'))=BINARY NEW.registration_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.clientMaterial.aad.configVersionId'))=BINARY NEW.config_version_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.clientMaterial.aad.materialId'))=BINARY NEW.operation_id AND JSON_EXTRACT(NEW.record_json,'$.clientMaterial.aad.owner')=JSON_EXTRACT(v.record_json,'$.owner') AND JSON_EXTRACT(NEW.record_json,'$.clientMaterial.aad.registrationGeneration')=JSON_EXTRACT(v.record_json,'$.generation') AND JSON_EXTRACT(NEW.record_json,'$.clientMaterial.aad.registrationRevision')=JSON_EXTRACT(NEW.record_json,'$.registrationRevision') AND JSON_EXTRACT(NEW.record_json,'$.clientMaterial.aad.authorizationEpoch')=0 AND JSON_EXTRACT(NEW.record_json,'$.clientMaterial.aad.subject')=CAST('null' AS JSON) AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.clientMaterial.aad.issuer'))=BINARY JSON_UNQUOTE(JSON_EXTRACT(v.record_json,'$.config.authentication.issuer')) AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.clientMaterial.aad.resource'))=BINARY JSON_UNQUOTE(JSON_EXTRACT(v.record_json,'$.config.authentication.resource')) AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.clientMaterial.aad.clientId'))=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.clientId')) AND JSON_LENGTH(JSON_EXTRACT(NEW.record_json,'$.clientMaterial.envelope'))=5 AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.clientMaterial.envelope.profile'))='mcp-aes-256-gcm-v1' AND JSON_TYPE(JSON_EXTRACT(NEW.record_json,'$.clientMaterial.envelope.keyId'))='STRING' AND OCTET_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.clientMaterial.envelope.keyId'))) BETWEEN 1 AND 128 AND OCTET_LENGTH(FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.clientMaterial.envelope.iv'))))=12 AND OCTET_LENGTH(FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.clientMaterial.envelope.tag'))))=16 AND OCTET_LENGTH(FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.clientMaterial.envelope.ciphertext')))) BETWEEN 1 AND 65536))) AND JSON_TYPE(JSON_EXTRACT(NEW.record_json,'$.clientId'))='STRING' AND OCTET_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.clientId'))) BETWEEN 1 AND 512 AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.responseSha256')) REGEXP '^[a-f0-9]{64}$' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.resultSha256')) REGEXP '^[a-f0-9]{64}$' AND JSON_EXTRACT(NEW.record_json,'$.completedAtMs')<JSON_EXTRACT(NEW.record_json,'$.deadlineAtMs') AND (JSON_EXTRACT(NEW.record_json,'$.clientSecretExpiresAtMs')=CAST('null' AS JSON) OR JSON_EXTRACT(NEW.record_json,'$.clientSecretExpiresAtMs')>CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED)) AND EXISTS (SELECT 1 FROM mcp_registry_versions v JOIN mcp_registry_controls c ON c.registration_id=v.registration_id WHERE v.config_version_id=NEW.config_version_id AND BINARY v.config_version_id=BINARY NEW.config_version_id AND v.registration_id=NEW.registration_id AND BINARY v.registration_id=BINARY NEW.registration_id AND JSON_UNQUOTE(JSON_EXTRACT(v.record_json,'$.config.authentication.kind'))='oauth_dynamic' AND JSON_EXTRACT(v.record_json,'$.owner')=JSON_EXTRACT(NEW.record_json,'$.owner') AND JSON_EXTRACT(v.record_json,'$.generation')=JSON_EXTRACT(NEW.record_json,'$.registrationGeneration') AND JSON_EXTRACT(v.record_json,'$.revision')<=JSON_EXTRACT(NEW.record_json,'$.registrationRevision') AND JSON_UNQUOTE(JSON_EXTRACT(c.record_json,'$.state'))='enabled' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(c.record_json,'$.currentVersionId'))=BINARY NEW.config_version_id AND JSON_EXTRACT(c.record_json,'$.revision')=JSON_EXTRACT(NEW.record_json,'$.registrationRevision') FOR SHARE)))) OR (NEW.operation_state='succeeded' AND OLD.operation_state='succeeded' AND JSON_REMOVE(NEW.record_json,'$.clientMaterial.envelope')=JSON_REMOVE(OLD.record_json,'$.clientMaterial.envelope') AND JSON_EXTRACT(NEW.record_json,'$.clientMaterial.envelope')=CAST('null' AS JSON)))) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP DCR transition or immutable identity is invalid'; END IF; END;

CREATE TRIGGER trg_mcp_registry_dynamic_clients_bd BEFORE DELETE ON mcp_registry_dynamic_clients FOR EACH ROW BEGIN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP DCR history is immutable'; END;

CREATE TRIGGER trg_mcp_registry_dynamic_clients_gate_bi BEFORE INSERT ON mcp_registry_dynamic_clients FOR EACH ROW BEGIN IF NOT EXISTS (SELECT 1 FROM mcp_registry_controls c WHERE c.registration_id=NEW.registration_id AND BINARY c.registration_id=BINARY NEW.registration_id AND (c.owner_tenant_id IS NULL OR (EXISTS (SELECT 1 FROM subject_lifecycle t WHERE t.tenant_id=c.owner_tenant_id AND t.subject_kind='tenant' AND t.subject_id=c.owner_tenant_id AND BINARY t.tenant_id=BINARY c.owner_tenant_id AND BINARY t.subject_id=BINARY c.owner_tenant_id AND t.state='active' FOR SHARE) AND (c.owner_user_id IS NULL OR EXISTS (SELECT 1 FROM subject_lifecycle u WHERE u.tenant_id=c.owner_tenant_id AND u.subject_kind='user' AND u.subject_id=c.owner_user_id AND BINARY u.tenant_id=BINARY c.owner_tenant_id AND BINARY u.subject_id=BINARY c.owner_user_id AND u.state='active' FOR SHARE)) AND NOT EXISTS (SELECT 1 FROM tenant_erasure_admissions a WHERE a.tenant_id=c.owner_tenant_id AND BINARY a.tenant_id=BINARY c.owner_tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_credential_revocation_fences f WHERE f.tenant_id=c.owner_tenant_id AND BINARY f.tenant_id=BINARY c.owner_tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_fences r WHERE r.tenant_id=c.owner_tenant_id AND BINARY r.tenant_id=BINARY c.owner_tenant_id FOR SHARE)))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP owner is not active'; END IF; END;

CREATE TRIGGER trg_mcp_registry_dynamic_clients_gate_bu BEFORE UPDATE ON mcp_registry_dynamic_clients FOR EACH ROW BEGIN IF ((OLD.operation_state='prepared' AND NEW.operation_state='sending') OR (OLD.operation_state='sending' AND NEW.operation_state='succeeded')) AND NOT EXISTS (SELECT 1 FROM mcp_registry_controls c WHERE c.registration_id=NEW.registration_id AND BINARY c.registration_id=BINARY NEW.registration_id AND (c.owner_tenant_id IS NULL OR (EXISTS (SELECT 1 FROM subject_lifecycle t WHERE t.tenant_id=c.owner_tenant_id AND t.subject_kind='tenant' AND t.subject_id=c.owner_tenant_id AND BINARY t.tenant_id=BINARY c.owner_tenant_id AND BINARY t.subject_id=BINARY c.owner_tenant_id AND t.state='active' FOR SHARE) AND (c.owner_user_id IS NULL OR EXISTS (SELECT 1 FROM subject_lifecycle u WHERE u.tenant_id=c.owner_tenant_id AND u.subject_kind='user' AND u.subject_id=c.owner_user_id AND BINARY u.tenant_id=BINARY c.owner_tenant_id AND BINARY u.subject_id=BINARY c.owner_user_id AND u.state='active' FOR SHARE)) AND NOT EXISTS (SELECT 1 FROM tenant_erasure_admissions a WHERE a.tenant_id=c.owner_tenant_id AND BINARY a.tenant_id=BINARY c.owner_tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_credential_revocation_fences f WHERE f.tenant_id=c.owner_tenant_id AND BINARY f.tenant_id=BINARY c.owner_tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_fences r WHERE r.tenant_id=c.owner_tenant_id AND BINARY r.tenant_id=BINARY c.owner_tenant_id FOR SHARE)))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP owner is not active'; END IF; END;

CREATE TRIGGER trg_mcp_dcr_pending_bi BEFORE INSERT ON mcp_registry_pending FOR EACH ROW BEGIN IF EXISTS (SELECT 1 FROM mcp_registry_versions v WHERE v.config_version_id=JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.configVersionId')) AND BINARY v.config_version_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.configVersionId')) AND v.registration_id=NEW.registration_id AND JSON_UNQUOTE(JSON_EXTRACT(v.record_json,'$.config.authentication.kind'))='oauth_dynamic' FOR SHARE) AND NOT EXISTS (SELECT 1 FROM mcp_registry_versions v JOIN mcp_registry_dynamic_clients d ON d.config_version_id=v.config_version_id AND d.registration_id=v.registration_id WHERE v.config_version_id=JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.configVersionId')) AND BINARY v.config_version_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.configVersionId')) AND v.registration_id=NEW.registration_id AND BINARY v.registration_id=BINARY NEW.registration_id AND d.operation_state='succeeded' AND JSON_EXTRACT(d.record_json,'$.registrationGeneration')=JSON_EXTRACT(v.record_json,'$.generation') AND JSON_EXTRACT(d.record_json,'$.registrationRevision')>=JSON_EXTRACT(v.record_json,'$.revision') AND JSON_EXTRACT(d.record_json,'$.owner')=JSON_EXTRACT(v.record_json,'$.owner') AND JSON_TYPE(JSON_EXTRACT(d.record_json,'$.clientId'))='STRING' AND (JSON_UNQUOTE(JSON_EXTRACT(v.record_json,'$.config.authentication.clientAuthentication'))='none' OR (JSON_UNQUOTE(JSON_EXTRACT(v.record_json,'$.config.authentication.clientAuthentication'))='client_secret_basic' AND JSON_TYPE(JSON_EXTRACT(d.record_json,'$.clientMaterial.envelope'))='OBJECT' AND (JSON_EXTRACT(d.record_json,'$.clientSecretExpiresAtMs')=CAST('null' AS JSON) OR JSON_EXTRACT(d.record_json,'$.clientSecretExpiresAtMs')>CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS UNSIGNED))))  FOR SHARE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP dynamic OAuth client is not ready'; END IF; END;

